function acquireGeometry(descriptor):
  key = canonicalKey(descriptor)
  if cache.has(key):
    cache[key].refCount += 1
    return cache[key].geometry
  geometry = buildGeometry(descriptor)
  validateGeometry(geometry)
  cache[key] = {geometry, refCount: 1}
  return geometry

function createInstance(geometry, material, M_i):
  obj = Mesh(geometry, material)
  obj.matrix = M_i
  return obj

function releaseGeometry(key):
  entry = cache[key]
  entry.refCount -= 1
  if entry.refCount == 0 and not entry.pinned:
    dispose(entry.geometry)
    delete cache[key]

function chooseLOD(object, camera):
  metric = projectedError(object.bounds, camera)
  candidate = coarsestLevelMeetingTolerance(metric, object.lodLevels)
  current = object.currentLOD
  if candidate != current:
    if crossesHysteresisBoundary(metric, current, candidate):
      object.currentLOD = candidate
  return object.lodLevels[object.currentLOD]

function sphereInFrustum(center, radius, planes):
  for plane in planes:
    if dot(plane.normal, center) + plane.d < -radius:
      return false
  return true

for object in objects:
  sphere = updateWorldSphere(object.localSphere, object.worldMatrix)
  object.visibleCandidate = sphereInFrustum(sphere.center, sphere.radius, planes)

function cellIndex(p):
  return floor((p - origin) / cellSize)

function insert(object):
  range = cellsCoveredBy(object.worldAABB)
  for cell in range:
    grid[cell].add(object.id)
  object.cells = range

function query(queryAABB):
  ids = set()
  for cell in cellsCoveredBy(queryAABB):
    ids.addAll(grid[cell])
  return [id for id in ids if exactOverlap(object[id].bounds, queryAABB)]

function invalidate(): dirty = true; requestFrameIfNeeded()

function frame(now):
  if not dirty and not animationActive: return
  if animationActive: updateAnimatedState(now)
  updateDirtySceneState()
  renderer.render(scene, camera)
  dirty = false
  if animationActive: requestAnimationFrame(frame)
  else: sleeping = true
